from typing import List

def count_aliens_disinfected(N: int, M: int, hands: List[int]) -> int:
    counter = 0
    disinfectant_remaining = M

    for num_hands in hands:
        if disinfectant_remaining >= num_hands:
            disinfectant_remaining -= num_hands
            counter += 1
        else:
            break

    return counter
